template<typename T>
class RingBuffer {
 std::vector<T> buf_;
 size_t head_ = 0, tail_ = 0, size_ = 0;
public:
 explicit RingBuffer(size_t cap) : buf_(cap) {}
 bool push(T val) {
 if (size_ == buf_.size()) return false;
 buf_[tail_] = std::move(val);
 tail_ = (tail_ + 1) % buf_.size();
 ++size_; return true;
 }
 std::optional<T> pop() {
